def append(list1, list2):
    return _append(list1, list2)


def _append(list1, list2):
    if not list1:
        return list2
    return [list1[0]] + _append(list1[1:], list2)


def concat(lists):
    return _concat(lists)


def _concat(lists):
    if not lists:
        return []
    return _append(lists[0], _concat(lists[1:]))


def filter(function, list):
    return _filter(function, list)


def _filter(function, list):
    if not list:
        return []
    head, tail = list[0], list[1:]
    return ([head] if function(head) else []) + _filter(function, tail)


def length(list):
    return _length(list)


def _length(list):
    if not list:
        return 0
    return 1 + _length(list[1:])


def map(function, list):
    return _map(function, list)


def _map(function, list):
    if not list:
        return []
    return [function(list[0])] + _map(function, list[1:])


def foldl(function, list, initial):
    return _foldl(function, list, initial)


def _foldl(function, list, initial):
    if not list:
        return initial
    return _foldl(function, list[1:], function(initial, list[0]))


def foldr(function, list, initial):
    return _foldr(function, list, initial)


def _foldr(function, list, initial):
    if not list:
        return initial
    return function(_foldr(function, list[1:], initial), list[0])


def reverse(list):
    return _reverse(list)


def _reverse(list):
    if not list:
        return []
    return _reverse(list[1:]) + [list[0]]

